// Minimal ANSI terminal styling, modelled on the semantics of the ansi_term crate.
use std::fmt::Write;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum Color {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Purple,
    Cyan,
    White,
    Fixed(u8),
    RGB(u8, u8, u8),
}

impl Color {
    fn write_fg(&self, s: &mut String) {
        match self {
            Color::Black => s.push_str("30"),
            Color::Red => s.push_str("31"),
            Color::Green => s.push_str("32"),
            Color::Yellow => s.push_str("33"),
            Color::Blue => s.push_str("34"),
            Color::Purple => s.push_str("35"),
            Color::Cyan => s.push_str("36"),
            Color::White => s.push_str("37"),
            Color::Fixed(n) => {
                let _ = write!(s, "38;5;{}", n);
            }
            Color::RGB(r, g, b) => {
                let _ = write!(s, "38;2;{};{};{}", r, g, b);
            }
        }
    }
    fn write_bg(&self, s: &mut String) {
        match self {
            Color::Black => s.push_str("40"),
            Color::Red => s.push_str("41"),
            Color::Green => s.push_str("42"),
            Color::Yellow => s.push_str("43"),
            Color::Blue => s.push_str("44"),
            Color::Purple => s.push_str("45"),
            Color::Cyan => s.push_str("46"),
            Color::White => s.push_str("47"),
            Color::Fixed(n) => {
                let _ = write!(s, "48;5;{}", n);
            }
            Color::RGB(r, g, b) => {
                let _ = write!(s, "48;2;{};{};{}", r, g, b);
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Default, Debug, Hash)]
pub struct Style {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub is_bold: bool,
    pub is_dimmed: bool,
    pub is_italic: bool,
    pub is_underline: bool,
    pub is_blink: bool,
    pub is_reverse: bool,
    pub is_hidden: bool,
    pub is_strikethrough: bool,
}

pub const RESET: &str = "\x1b[0m";

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn is_plain(&self) -> bool {
        *self == Style::default()
    }
    pub fn fg(c: Color) -> Style {
        Style { foreground: Some(c), ..Style::default() }
    }
    pub fn prefix(&self) -> String {
        if self.is_plain() {
            return String::new();
        }
        let mut s = String::from("\x1b[");
        let mut written_anything = false;
        let mut push = |s: &mut String, code: &str, w: &mut bool| {
            if *w {
                s.push(';');
            }
            *w = true;
            s.push_str(code);
        };
        if self.is_bold {
            push(&mut s, "1", &mut written_anything);
        }
        if self.is_dimmed {
            push(&mut s, "2", &mut written_anything);
        }
        if self.is_italic {
            push(&mut s, "3", &mut written_anything);
        }
        if self.is_underline {
            push(&mut s, "4", &mut written_anything);
        }
        if self.is_blink {
            push(&mut s, "5", &mut written_anything);
        }
        if self.is_reverse {
            push(&mut s, "7", &mut written_anything);
        }
        if self.is_hidden {
            push(&mut s, "8", &mut written_anything);
        }
        if self.is_strikethrough {
            push(&mut s, "9", &mut written_anything);
        }
        if let Some(bg) = self.background {
            if written_anything {
                s.push(';');
            }
            written_anything = true;
            bg.write_bg(&mut s);
        }
        if let Some(fg) = self.foreground {
            if written_anything {
                s.push(';');
            }
            fg.write_fg(&mut s);
        }
        s.push('m');
        s
    }
    pub fn suffix(&self) -> &'static str {
        if self.is_plain() {
            ""
        } else {
            RESET
        }
    }
    pub fn paint(&self, text: &str) -> String {
        let mut s = self.prefix();
        s.push_str(text);
        s.push_str(self.suffix());
        s
    }
}

enum Difference {
    ExtraStyles(Style),
    Reset,
    NoDifference,
}

fn difference(first: &Style, next: &Style) -> Difference {
    if first == next {
        return Difference::NoDifference;
    }
    if (first.is_bold && !next.is_bold)
        || (first.is_dimmed && !next.is_dimmed)
        || (first.is_italic && !next.is_italic)
        || (first.is_underline && !next.is_underline)
        || (first.is_blink && !next.is_blink)
        || (first.is_reverse && !next.is_reverse)
        || (first.is_hidden && !next.is_hidden)
        || (first.is_strikethrough && !next.is_strikethrough)
    {
        return Difference::Reset;
    }
    if first.foreground.is_some() && next.foreground.is_none() {
        return Difference::Reset;
    }
    if first.background.is_some() && next.background.is_none() {
        return Difference::Reset;
    }
    let mut extra = Style::default();
    if first.is_bold != next.is_bold {
        extra.is_bold = true;
    }
    if first.is_dimmed != next.is_dimmed {
        extra.is_dimmed = true;
    }
    if first.is_italic != next.is_italic {
        extra.is_italic = true;
    }
    if first.is_underline != next.is_underline {
        extra.is_underline = true;
    }
    if first.is_blink != next.is_blink {
        extra.is_blink = true;
    }
    if first.is_reverse != next.is_reverse {
        extra.is_reverse = true;
    }
    if first.is_hidden != next.is_hidden {
        extra.is_hidden = true;
    }
