                Difference::ExtraStyles(e) => out.push_str(&e.prefix()),
                Difference::Reset => {
                    out.push_str(RESET);
                    out.push_str(&style.prefix());
                }
                Difference::NoDifference => {}
            },
        }
        out.push_str(text);
        prev = Some(style);
    }
    if let Some(p) = prev {
        if !p.is_plain() {
