// Approximation of sRGB -> xterm-256 palette mapping.

const LEVELS: [u8; 6] = [0, 95, 135, 175, 215, 255];
const THRESHOLDS: [[u8; 5]; 3] = [[38, 115, 155, 196, 235], [36, 116, 154, 195, 235], [35, 115, 155, 195, 235]];

fn lin(c: u8) -> f64 {
    let c = c as f64 / 255.0;
    if c <= 0.04045 {
        c / 12.92
    } else {
        ((c + 0.055) / 1.055).powf(2.4)
    }
}

fn lab(r: u8, g: u8, b: u8) -> (f64, f64, f64) {
    let (r, g, b) = (lin(r), lin(g), lin(b));
    let x = (0.4124564 * r + 0.3575761 * g + 0.1804375 * b) / 0.95047;
    let y = 0.2126729 * r + 0.7151522 * g + 0.0721750 * b;
    let z = (0.0193339 * r + 0.1191920 * g + 0.9503041 * b) / 1.08883;
    let f = |t: f64| {
        if t > 216.0 / 24389.0 {
            t.cbrt()
        } else {
            (24389.0 / 27.0 * t + 16.0) / 116.0
        }
    };
    let (fx, fy, fz) = (f(x), f(y), f(z));
    (116.0 * fy - 16.0, 500.0 * (fx - fy), 200.0 * (fy - fz))
}

fn d76(a: (f64, f64, f64), b: (f64, f64, f64)) -> f64 {
    (a.0 - b.0).powi(2) + (a.1 - b.1).powi(2) + (a.2 - b.2).powi(2)
}

fn cube_index(v: u8, ch: usize) -> usize {
    THRESHOLDS[ch].iter().filter(|t| v >= **t).count()
}

pub fn ansi256_from_rgb(r: u8, g: u8, b: u8) -> u8 {
    if let Some(n) = crate::ansi256_table::lookup(r, g, b) {
        return n;
    }
    let (ri, gi, bi) = (cube_index(r, 0), cube_index(g, 1), cube_index(b, 2));
    let cube = (LEVELS[ri], LEVELS[gi], LEVELS[bi]);
    let cube_n = 16 + 36 * ri + 6 * gi + bi;
    let l = lab(r, g, b);
    let mut best_grey = 0;
    let mut best_d = f64::MAX;
    for i in 0..24 {
        let v = 8 + 10 * i as u8;
        let d = d76(l, lab(v, v, v));
        if d < best_d {
            best_d = d;
            best_grey = i;
        }
    }
    let dc = d76(l, lab(cube.0, cube.1, cube.2));
    if dc <= best_d {
        cube_n as u8
    } else {
        232 + best_grey as u8
    }
}
