struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    _src: &'a str,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }
}

/// Parse git config text into (key, value) entries. Value None means "key present without '='".
pub fn parse_config_text(text: &str) -> Vec<(String, Option<String>)> {
    let mut p = Parser { chars: text.chars().collect(), pos: 0, _src: text };
    let mut entries = Vec::new();
    let mut section = String::new(); // "section" or "section.subsection" (normalized)
    loop {
        // skip whitespace
        while let Some(c) = p.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                p.next();
            } else {
                break;
            }
        }
        let c = match p.peek() {
            None => break,
            Some(c) => c,
        };
        if c == '#' || c == ';' {
            while let Some(c) = p.next() {
                if c == '\n' {
                    break;
                }
            }
            continue;
        }
        if c == '[' {
            p.next();
            let mut name = String::new();
            let mut sub: Option<String> = None;
            loop {
                match p.next() {
                    None => break,
                    Some(']') => break,
                    Some('"') => {
                        let mut s = String::new();
                        loop {
                            match p.next() {
                                None => break,
                                Some('"') => break,
                                Some('\\') => {
                                    if let Some(c) = p.next() {
                                        s.push(c);
                                    }
                                }
                                Some(c) => s.push(c),
                            }
                        }
                        sub = Some(s);
                    }
                    Some(c) if c == ' ' || c == '\t' => {}
                    Some(c) => name.push(c),
                }
            }
            let name_l = name.to_lowercase();
            section = match sub {
                Some(s) => format!("{}.{}", name_l, s),
                None => {
                    // old-style [section.subsection]
                    if let Some(i) = name.find('.') {
                        format!("{}.{}", name[..i].to_lowercase(), name[i + 1..].to_lowercase())
                    } else {
                        name_l
                    }
                }
            };
            continue;
        }
        // key
        let mut key = String::new();
        while let Some(c) = p.peek() {
            if c.is_alphanumeric() || c == '-' || c == '_' {
                key.push(c);
                p.next();
            } else {
                break;
            }
        }
        if key.is_empty() {
            // garbage; skip line
            while let Some(c) = p.next() {
                if c == '\n' {
                    break;
                }
            }
            continue;
        }
        while let Some(c) = p.peek() {
            if c == ' ' || c == '\t' {
                p.next();
            } else {
                break;
            }
        }
        let full_key = format!("{}.{}", section, key.to_lowercase());
        match p.peek() {
            Some('=') => {
                p.next();
                // parse value
                let mut value = String::new();
                let mut in_quote = false;
                let mut pending_ws = String::new();
                let mut started = false;
                loop {
                    let c = match p.next() {
                        None => break,
                        Some(c) => c,
                    };
                    if c == '\n' {
                        break;
                    }
                    if c == '\r' && p.peek() == Some('\n') {
                        continue;
                    }
                    if !in_quote && (c == '#' || c == ';') {
                        while let Some(c) = p.next() {
                            if c == '\n' {
                                break;
                            }
                        }
                        break;
                    }
                    if !in_quote && (c == ' ' || c == '\t') {
                        if started {
                            pending_ws.push(c);
                        }
                        continue;
                    }
                    if !pending_ws.is_empty() {
                        value.push_str(&pending_ws);
                        pending_ws.clear();
                    }
                    started = true;
                    if c == '"' {
                        in_quote = !in_quote;
                        continue;
                    }
                    if c == '\\' {
                        match p.next() {
                            Some('\n') => {
                                continue;
                            }
                            Some('\r') => {
                                if p.peek() == Some('\n') {
                                    p.next();
                                }
                                continue;
                            }
                            Some('n') => value.push('\n'),
                            Some('t') => value.push('\t'),
                            Some('b') => {
                                value.pop();
                            }
                            Some('\\') => value.push('\\'),
                            Some('"') => value.push('"'),
                            Some(c) => {
                                value.push('\\');
                                value.push(c);
                            }
                            None => {}
                        }
                        continue;
                    }
                    if in_quote && (c == ' ' || c == '\t') {
                        value.push(c);
                        continue;
                    }
                    value.push(c);
                }
                entries.push((full_key, Some(value)));
            }
            _ => {
                // no value: skip rest of line (comments)
                while let Some(c) = p.next() {
                    if c == '\n' {
                        break;
                    }
                }
                entries.push((full_key, None));
            }
        }
    }
    entries
}

fn load_file(path: &Path, out: &mut Vec<(String, Option<String>)>, depth: usize, git_dir: Option<&Path>) -> bool {
    if depth > 10 {
        return false;
    }
    let text = match std::fs::read(path) {
        Ok(b) => String::from_utf8_lossy(&b).into_owned(),
        Err(_) => return false,
    };
    let entries = parse_config_text(&text);
    let base = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    for (k, v) in entries {
        let is_include = k == "include.path";
        let include_if = if !is_include && k.starts_with("includeif.") && k.ends_with(".path") {
            Some(k["includeif.".len()..k.len() - ".path".len()].to_string())
        } else {
            None
        };
        out.push((k.clone(), v.clone()));
        if let Some(v) = &v {
            let mut do_include = is_include;
            if let Some(cond) = include_if {
                do_include = eval_include_if(&cond, path, git_dir);
            }
            if do_include {
                let p = expand_tilde(v);
                let p = if p.is_absolute() { p } else { base.join(p) };
                load_file(&p, out, depth + 1, git_dir);
            }
        }
    }
    true
}

fn eval_include_if(cond: &str, config_path: &Path, git_dir: Option<&Path>) -> bool {
    let (kind, pat) = match cond.find(':') {
        Some(i) => (&cond[..i], &cond[i + 1..]),
        None => return false,
    };
    match kind {
        "gitdir" | "gitdir/i" => {
            let git_dir = match git_dir {
                Some(g) => g,
                None => return false,
            };
            let mut pat = pat.to_string();
            if pat.starts_with("~/") {
                if let Some(h) = home_dir() {
                    pat = format!("{}/{}", h.display(), &pat[2..]);
                }
            } else if pat.starts_with("./") {
                if let Some(parent) = config_path.parent() {
                    pat = format!("{}/{}", parent.display(), &pat[2..]);
                }
            } else if !pat.starts_with('/') {
                pat = format!("**/{}", pat);
            }
            if pat.ends_with('/') {
                pat.push_str("**");
            }
            let gd = git_dir.to_string_lossy().to_string();
            let (pat, gd) = if kind == "gitdir/i" { (pat.to_lowercase(), gd.to_lowercase()) } else { (pat, gd) };
            glob_match(&pat, &gd)
        }
        _ => false,
    }
}

fn glob_match(pat: &str, s: &str) -> bool {
    fn rec(p: &[char], s: &[char]) -> bool {
        if p.is_empty() {
            return s.is_empty();
        }
        if p.len() >= 2 && p[0] == '*' && p[1] == '*' {
            let rest = if p.len() > 2 && p[2] == '/' { &p[3..] } else { &p[2..] };
            for i in 0..=s.len() {
                if rec(rest, &s[i..]) {
                    return true;
                }
            }
            return false;
        }
        match p[0] {
            '*' => {
                for i in 0..=s.len() {
                    if i > 0 && s[i - 1] == '/' {
                        break;
                    }
                    if rec(&p[1..], &s[i..]) {
                        return true;
                    }
                }
                false
            }
            '?' => !s.is_empty() && s[0] != '/' && rec(&p[1..], &s[1..]),
            c => !s.is_empty() && s[0] == c && rec(&p[1..], &s[1..]),
        }
    }
    let p: Vec<char> = pat.chars().collect();
    let s: Vec<char> = s.chars().collect();
    rec(&p, &s)
}

/// Discover a git repository from dir: returns (git_dir, workdir)
pub fn discover_repo(dir: &Path) -> Option<(PathBuf, Option<PathBuf>)> {
    let mut d = Some(dir.to_path_buf());
    while let Some(cur) = d {
        let dotgit = cur.join(".git");
        if dotgit.is_dir() {
            if dotgit.join("HEAD").exists() {
                return Some((dotgit, Some(cur)));
            }
        } else if dotgit.is_file() {
            if let Ok(t) = std::fs::read_to_string(&dotgit) {
                if let Some(rest) = t.trim().strip_prefix("gitdir:") {
                    let p = PathBuf::from(rest.trim());
                    let p = if p.is_absolute() { p } else { cur.join(p) };
                    return Some((p, Some(cur)));
                }
            }
        } else if cur.join("HEAD").is_file() && cur.join("objects").is_dir() && cur.join("refs").is_dir() {
            return Some((cur.clone(), None));
        }
        d = cur.parent().map(|p| p.to_path_buf());
    }
    None
}

fn parse_env_parameters(s: &str) -> HashMap<String, String> {
    let re = regex::Regex::new(r"(?:'(delta\.[a-z-]+)=([^']+)'|'(delta\.[a-z-]+)'='([^']+)')").unwrap();
    let mut map = HashMap::new();
    for cap in re.captures_iter(s) {
        let (k, v) = if let Some(k) = cap.get(1) {
            (k.as_str(), cap.get(2).unwrap().as_str())
        } else {
            (cap.get(3).unwrap().as_str(), cap.get(4).unwrap().as_str())
        };
        map.insert(k.to_string(), v.to_string());
    }
    map
}

impl GitConfig {
    pub fn try_create() -> Option<GitConfig> {
        let cwd = std::env::current_dir().ok();
        let repo = cwd.as_deref().and_then(discover_repo);
        let mut entries = Vec::new();
        let git_dir = repo.as_ref().map(|r| r.0.clone());
        // system
        if std::env::var_os("GIT_CONFIG_NOSYSTEM").is_none() {
            load_file(Path::new("/etc/gitconfig"), &mut entries, 0, git_dir.as_deref());
        }
        // xdg
        let xdg = match std::env::var_os("XDG_CONFIG_HOME").filter(|x| !x.is_empty()) {
            Some(x) => Some(PathBuf::from(x).join("git").join("config")),
            None => home_dir().map(|h| h.join(".config").join("git").join("config")),
        };
        if let Some(x) = xdg {
            load_file(&x, &mut entries, 0, git_dir.as_deref());
        }
        if let Some(h) = home_dir() {
            load_file(&h.join(".gitconfig"), &mut entries, 0, git_dir.as_deref());
        }
        if let Some((gd, _)) = &repo {
            load_file(&gd.join("config"), &mut entries, 0, git_dir.as_deref());
        }
        Some(GitConfig {
            entries,
            env_entries: Self::env_params(),
            enabled: true,
            repo_dir: repo.as_ref().and_then(|r| r.1.clone()),
            git_dir,
        })
    }

    fn env_params() -> HashMap<String, String> {
        match std::env::var("GIT_CONFIG_PARAMETERS") {
            Ok(s) => parse_env_parameters(&s),
            Err(_) => HashMap::new(),
        }
    }

    pub fn from_path(path: &Path, honor_env_var: bool) -> Result<GitConfig, String> {
        let mut entries = Vec::new();
        if !path.exists() {
            // libgit2 tolerates missing files when opening explicitly? Treat as error.
        }
        load_file(path, &mut entries, 0, None);
        let cwd = std::env::current_dir().ok();
        let repo = cwd.as_deref().and_then(discover_repo);
        Ok(GitConfig {
            entries,
            env_entries: if honor_env_var { Self::env_params() } else { HashMap::new() },
            enabled: true,
            repo_dir: repo.as_ref().and_then(|r| r.1.clone()),
            git_dir: repo.as_ref().map(|r| r.0.clone()),
        })
    }

    pub fn empty() -> GitConfig {
        GitConfig { enabled: true, ..Default::default() }
    }

    fn raw_get(&self, key: &str) -> Option<Option<String>> {
        if !self.enabled {
            return None;
        }
        let nk = normalize_key(key);
        for (k, v) in self.entries.iter().rev() {
            if *k == nk {
                return Some(v.clone());
            }
        }
        None
    }

    pub fn get_string(&self, key: &str) -> Option<String> {
        if !self.enabled {
            return None;
        }
        if let Some(v) = self.env_entries.get(key) {
            return Some(v.clone());
        }
        match self.raw_get(key) {
            Some(Some(v)) => Some(v),
            Some(None) => Some(String::new()),
            None => None,
        }
    }

    pub fn get_bool(&self, key: &str) -> Option<bool> {
        if !self.enabled {
            return None;
        }
        if let Some(v) = self.env_entries.get(key) {
            return parse_bool(v);
        }
        match self.raw_get(key) {
            Some(Some(v)) => parse_bool(&v),
            Some(None) => Some(true),
            None => None,
        }
    }

    pub fn get_i64(&self, key: &str) -> Option<i64> {
        let s = if let Some(v) = self.env_entries.get(key) {
            v.clone()
        } else {
            match self.raw_get(key) {
                Some(Some(v)) => v,
                _ => return None,
            }
        };
        if !self.enabled {
            return None;
        }
        parse_git_int(&s)
    }

    /// All entries whose key starts with the prefix (in priority order, last wins)
    pub fn entries_with_prefix(&self, prefix: &str) -> Vec<(String, String)> {
        let mut out = Vec::new();
        for (k, v) in &self.entries {
            if k.starts_with(prefix) {
                out.push((k.clone(), v.clone().unwrap_or_default()));
            }
        }
        out
    }

    pub fn all_entries(&self) -> &Vec<(String, Option<String>)> {
        &self.entries
    }
}

pub fn parse_bool(s: &str) -> Option<bool> {
    match s.to_lowercase().as_str() {
        "true" | "yes" | "on" | "1" => Some(true),
        "false" | "no" | "off" | "0" | "" => Some(false),
        _ => {
            if let Ok(n) = s.parse::<i64>() {
                Some(n != 0)
            } else {
                None
            }
        }
    }
}

fn parse_git_int(s: &str) -> Option<i64> {
    let s = s.trim();
    let (num, mult) = match s.chars().last() {
        Some('k') | Some('K') => (&s[..s.len() - 1], 1024),
        Some('m') | Some('M') => (&s[..s.len() - 1], 1024 * 1024),
        Some('g') | Some('G') => (&s[..s.len() - 1], 1024 * 1024 * 1024),
        _ => (s, 1),
    };
    num.parse::<i64>().ok().map(|n| n * mult)
}
