    }

    pub fn from_colors(foreground: Option<Color>, background: Option<Color>) -> Style {
        Style {
            ansi_term_style: ansi_term::Style { foreground, background, ..ansi_term::Style::default() },
            ..Style::default()
        }
    }

    pub fn paint(&self, s: &str) -> String {
