    }

    pub fn get_background_color(&self) -> Option<Color> {
        self.ansi_term_style.background
    }

    pub fn is_applied_to_whitespace(&self) -> bool {
        let s = &self.ansi_term_style;
        s.is_reverse || s.is_underline || s.background.is_some()
    }

    pub fn to_painted_string(&self) -> String {
