    }

    pub fn from_str(
        style_string: &str,
        default: Option<Style>,
        decoration_style_string: Option<&str>,
        true_color: bool,
        git_config: Option<&GitConfig>,
    ) -> Style {
        let (ansi_term_style, is_omitted, is_raw, is_syntax_highlighted) =
            parse_ansi_term_style(style_string, default, true_color, git_config);
        let decoration_style =
            decoration_style_from_str(decoration_style_string.unwrap_or(""), true_color, git_config);
        Style { ansi_term_style, is_emph: false, is_omitted, is_raw, is_syntax_highlighted, decoration_style }
    }

    pub fn from_str_with_handling_of_special_decoration_attributes(
        style_string: &str,
        default: Option<Style>,
        decoration_style_string: Option<&str>,
        true_color: bool,
        git_config: Option<&GitConfig>,
    ) -> Style {
        let (special_attributes, style_string) = extract_special_decoration_attributes(style_string, false);
        let mut style = Style::from_str(&style_string, default, decoration_style_string, true_color, git_config);
        style.decoration_style = apply_special_decoration_attributes(&style, special_attributes);
