    }

    /// Interpret a git color config string (e.g. "bold red ul") as a Style.
    pub fn from_git_str(git_style_string: &str) -> Style {
        let mut style = ansi_term::Style::new();
        let mut seen_fg = false;
        let mut seen_bg = false;
        for word in git_style_string.split_whitespace() {
            let w = word.to_lowercase();
            match w.as_str() {
                "bold" => style.is_bold = true,
                "dim" => style.is_dimmed = true,
                "italic" => style.is_italic = true,
                "ul" | "underline" => style.is_underline = true,
                "blink" => style.is_blink = true,
                "reverse" => style.is_reverse = true,
                "strike" => style.is_strikethrough = true,
