fn parse_git_color(s: &str) -> Option<Color> {
    match s {
        "normal" | "default" => None,
        "black" => Some(Color::Black),
        "red" => Some(Color::Red),
        "green" => Some(Color::Green),
        "yellow" => Some(Color::Yellow),
        "blue" => Some(Color::Blue),
        "magenta" => Some(Color::Purple),
        "cyan" => Some(Color::Cyan),
        "white" => Some(Color::White),
        _ => {
            if let Some(rest) = s.strip_prefix("bright") {
                if let Some(n) = color::ansi_16_color_name_to_number(rest) {
                    return Some(Color::Fixed(n + 8));
                }
            }
            if let Ok(n) = s.parse::<u8>() {
                return Some(Color::Fixed(n));
            }
            if let Some(c) = color::Rgba::from_hex_str(s) {
                return Some(Color::RGB(c.r, c.g, c.b));
            }
            None
        }
    }
}

impl std::fmt::Display for Style {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        if self.is_raw {
            return write!(f, "raw");
        }
        let mut words = Vec::<String>::new();
        if self.is_omitted {
            words.push("omit".to_string());
        }
        let s = &self.ansi_term_style;
        if s.is_blink {
            words.push("blink".to_string());
        }
        if s.is_bold {
            words.push("bold".to_string());
        }
        if s.is_dimmed {
