        }
        if s.is_italic {
            words.push("italic".to_string());
        }
        if s.is_reverse {
            words.push("reverse".to_string());
        }
        if s.is_strikethrough {
            words.push("strike".to_string());
        }
        if s.is_underline {
            words.push("ul".to_string());
        }
        match (self.is_syntax_highlighted, s.foreground) {
            (true, _) => words.push("syntax".to_string()),
            (false, Some(c)) => words.push(color::color_to_string(c)),
            (false, None) => words.push("normal".to_string()),
        }
        if let Some(c) = s.background {
            words.push(color::color_to_string(c));
        }
        write!(f, "{}", words.join(" "))
    }
}

fn split_words(s: &str) -> Vec<String> {
    s.to_lowercase()
        .split_whitespace()
        .map(|w| w.trim_matches(|c| c == '"' || c == '\'').to_string())
        .collect()
}

pub fn parse_ansi_term_style(
    s: &str,
    default: Option<Style>,
    true_color: bool,
    git_config: Option<&GitConfig>,
) -> (ansi_term::Style, bool, bool, bool) {
    let mut style = ansi_term::Style::new();
    let mut seen_foreground = false;
    let mut seen_background = false;
    let mut foreground_is_auto = false;
    let mut background_is_auto = false;
    let mut is_omitted = false;
    let mut is_raw = false;
    let mut seen_omit = false;
    let mut seen_raw = false;
    let mut is_syntax_highlighted = false;
    for word in split_words(s) {
        let word = word.as_str();
        if word == "blink" {
            style.is_blink = true;
        } else if word == "bold" {
            style.is_bold = true;
        } else if word == "dim" {
            style.is_dimmed = true;
        } else if word == "hidden" {
            style.is_hidden = true;
        } else if word == "italic" {
            style.is_italic = true;
        } else if word == "omit" {
            seen_omit = true;
            is_omitted = true;
        } else if word == "reverse" {
            style.is_reverse = true;
        } else if word == "raw" {
            seen_raw = true;
            is_raw = true;
        } else if word == "strike" {
            style.is_strikethrough = true;
        } else if word == "ul" || word == "underline" {
            style.is_underline = true;
        } else if word == "line-number" || word == "file" {
            // allowed in hunk-header-style
        } else if !seen_foreground {
            if word == "syntax" {
                is_syntax_highlighted = true;
            } else if word == "auto" {
                foreground_is_auto = true;
                style.foreground = default.and_then(|s| s.ansi_term_style.foreground);
                is_syntax_highlighted = default.map(|s| s.is_syntax_highlighted).unwrap_or(false);
            } else {
                style.foreground = parse_color(word, true_color, git_config);
            }
            seen_foreground = true;
        } else if !seen_background {
            if word == "syntax" {
                fatal("You have used the special color 'syntax' as a background color (second color in a style string). It may only be used as a foreground color (first color in a style string).");
            } else if word == "auto" {
                background_is_auto = true;
                style.background = default.and_then(|s| s.ansi_term_style.background);
            } else {
                style.background = parse_color(word, true_color, git_config);
            }
            seen_background = true;
        } else {
            fatal(&format!("Invalid style string: {}. See the STYLES section of delta --help.", s));
        }
    }
    if foreground_is_auto && background_is_auto {
        if !seen_omit {
            is_omitted = default.map(|s| s.is_omitted).unwrap_or(false);
        }
        if !seen_raw {
            is_raw = default.map(|s| s.is_raw).unwrap_or(false);
        }
    }
    (style, is_omitted, is_raw, is_syntax_highlighted)
}

pub fn parse_color(s: &str, true_color: bool, git_config: Option<&GitConfig>) -> Option<Color> {
    if s == "normal" {
        return None;
    }
    let die = || -> ! { fatal(&format!("Invalid color or style attribute: {}", s)) };
    let rgba = if s.starts_with('#') {
        color::Rgba::from_hex_str(s).unwrap_or_else(|| die())
    } else {
        let n = s.parse::<u8>().ok().or_else(|| color::ansi_16_color_name_to_number(s));
        match n {
            Some(n) => color::Rgba { r: n, g: 0, b: 0, a: 0 },
            None => match color::css_color(s) {
                Some(v) => color::Rgba::new((v >> 16) as u8, (v >> 8) as u8, v as u8),
                None => {
                    // named color in git config
                    match git_config.and_then(|gc| gc.get_string(&format!("delta.{}", s))) {
                        Some(val) => {
                            return parse_color(&val.to_lowercase(), true_color, git_config);
                        }
                        None => die(),
                    }
                }
            },
        }
    };
    color::to_ansi_color(rgba, true_color)
}

pub fn decoration_style_from_str(style_string: &str, true_color: bool, git_config: Option<&GitConfig>) -> DecorationStyle {
    let (special_attributes, style_string) = extract_special_decoration_attributes(style_string, true);
    let (style, _is_omitted, is_raw, is_syntax_highlighted) =
        parse_ansi_term_style(&style_string, None, true_color, git_config);
    if is_raw {
        fatal("'raw' may not be used in a decoration style.");
    }
    if is_syntax_highlighted {
        fatal("'syntax' may not be used in a decoration style.");
    }
    match special_attributes {
        0 => DecorationStyle::NoDecoration,
        b if b == BOX => DecorationStyle::Box(style),
        b if b == UNDERLINE => DecorationStyle::Underline(style),
        b if b == OVERLINE => DecorationStyle::Overline(style),
        b if b == UNDERLINE | OVERLINE => DecorationStyle::UnderOverline(style),
        b if b == BOX | UNDERLINE => DecorationStyle::BoxWithUnderline(style),
        b if b == BOX | OVERLINE => DecorationStyle::BoxWithOverline(style),
        b if b == BOX | UNDERLINE | OVERLINE => DecorationStyle::BoxWithUnderOverline(style),
        _ => DecorationStyle::NoDecoration,
    }
}

fn apply_special_decoration_attributes(style: &Style, special_attributes: u8) -> DecorationStyle {
    let s = style.decoration_style.ansi_term_style().unwrap_or_default();
    match special_attributes {
        0 => style.decoration_style,
        b if b == BOX => DecorationStyle::Box(s),
        b if b == UNDERLINE => DecorationStyle::Underline(s),
        b if b == OVERLINE => DecorationStyle::Overline(s),
        b if b == UNDERLINE | OVERLINE => DecorationStyle::UnderOverline(s),
        b if b == BOX | UNDERLINE => DecorationStyle::BoxWithUnderline(s),
        b if b == BOX | OVERLINE => DecorationStyle::BoxWithOverline(s),
        b if b == BOX | UNDERLINE | OVERLINE => DecorationStyle::BoxWithUnderOverline(s),
        _ => style.decoration_style,
    }
}

fn extract_special_decoration_attributes(style_string: &str, is_decoration: bool) -> (u8, String) {
    let mut attributes = 0u8;
    let mut new_words = Vec::new();
    for token in split_words(style_string) {
        match token.as_str() {
            "box" => attributes |= BOX,
            "overline" => attributes |= OVERLINE,
            "ol" if is_decoration => attributes |= OVERLINE,
            "underline" => attributes |= UNDERLINE,
            "ul" if is_decoration => attributes |= UNDERLINE,
            "none" | "plain" => attributes |= PLAIN,
            _ => new_words.push(token),
        }
    }
    (attributes, new_words.join(" "))
}
