fn get_from_gitconfig(kind: Kind, key: &str, gc: &GitConfig) -> Option<Value> {
    match kind {
        Kind::Bool => gc.get_bool(key).map(Value::Bool),
        Kind::Str | Kind::Enum(_) => gc.get_string(key).map(Value::Str),
        Kind::OptStr | Kind::OptEnum(_) => gc.get_string(key).map(|s| Value::OptStr(Some(s))),
        Kind::Usize => gc.get_i64(key).filter(|n| *n >= 0).map(|n| Value::Usize(n as usize)),
        Kind::F64 => gc.get_string(key).and_then(|s| s.trim().parse::<f64>().ok()).map(Value::F64),
    }
}

fn coerce(kind: Kind, v: Value) -> Value {
    match (kind, v) {
        (Kind::OptStr, Value::Str(s)) | (Kind::OptEnum(_), Value::Str(s)) => Value::OptStr(Some(s)),
        (Kind::Str, Value::OptStr(Some(s))) | (Kind::Enum(_), Value::OptStr(Some(s))) => Value::Str(s),
        (Kind::Usize, Value::Str(s)) => Value::Usize(s.parse().unwrap_or(0)),
        (Kind::Bool, Value::Str(s)) => Value::Bool(s == "true"),
        (_, v) => v,
    }
}

pub fn get_option_value(
    option: &str,
    builtin: &[BuiltinFeature],
    opt: &Opt,
    git_config: Option<&GitConfig>,
) -> Option<Value> {
    let kind = *opt.kinds.get(option)?;
    if let Some(gc) = git_config {
        if let Some(v) = get_from_gitconfig(kind, &format!("delta.{}", option), gc) {
            return Some(v);
        }
    }
    if let Some(features) = opt.os("features") {
        for feature in features.split_whitespace().rev() {
            if let Some(gc) = git_config {
                if let Some(v) = get_from_gitconfig(kind, &format!("delta.{}.{}", feature, option), gc) {
                    return Some(v);
                }
            }
            if let Some(bf) = builtin.iter().find(|f| f.name == feature) {
                if let Some(bo) = bf.get(option) {
                    let v = match features::eval(bo, opt, git_config) {
                        Provenanced::GitConfigValue(v) => v,
                        Provenanced::DefaultValue(v) => v,
                    };
                    return Some(coerce(kind, v));
                }
            }
        }
    }
    None
}

fn set_option(name: &str, opt: &mut Opt, builtin: &[BuiltinFeature], git_config: Option<&GitConfig>) {
    if opt.supplied(name) {
        return;
    }
