// ANSI escape sequence utilities.
use crate::ansi_term::{Color, Style};
use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

pub const ANSI_CSI_CLEAR_TO_EOL: &str = "\x1b[0K";
pub const ANSI_CSI_CLEAR_TO_BOL: &str = "\x1b[1K";
pub const ANSI_SGR_RESET: &str = "\x1b[0m";
pub const ANSI_SGR_REVERSE: &str = "\x1b[7m";

#[derive(Debug, Clone, PartialEq)]
pub enum Element<'a> {
    Text(&'a str),
    Csi(&'a str), // full sequence including ESC [
    Osc(&'a str), // full sequence
    Esc(&'a str),
}

/// Split a string into text and escape-sequence elements.
pub fn elements(s: &str) -> Vec<Element<'_>> {
    let bytes = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    let mut text_start = 0;
    while i < bytes.len() {
        if bytes[i] == 0x1b {
            if text_start < i {
                out.push(Element::Text(&s[text_start..i]));
            }
            let start = i;
            if i + 1 < bytes.len() && bytes[i + 1] == b'[' {
                let mut j = i + 2;
                while j < bytes.len() && !(0x40..=0x7e).contains(&bytes[j]) {
                    j += 1;
                }
                let end = (j + 1).min(bytes.len());
                out.push(Element::Csi(&s[start..end]));
                i = end;
            } else if i + 1 < bytes.len() && bytes[i + 1] == b']' {
                let mut j = i + 2;
                let mut end = bytes.len();
                while j < bytes.len() {
                    if bytes[j] == 0x07 {
                        end = j + 1;
                        break;
                    }
                    if bytes[j] == 0x1b && j + 1 < bytes.len() && bytes[j + 1] == b'\\' {
                        end = j + 2;
                        break;
                    }
                    j += 1;
                }
                out.push(Element::Osc(&s[start..end]));
                i = end;
            } else {
                // two-byte escape (or lone ESC)
                let mut end = i + 1;
                if end < bytes.len() {
                    // advance one char
                    let ch_len = s[end..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
                    end += ch_len;
                }
                out.push(Element::Esc(&s[start..end]));
                i = end;
            }
            text_start = i;
        } else {
            i += 1;
        }
    }
    if text_start < bytes.len() {
        out.push(Element::Text(&s[text_start..]));
    }
    out
}

pub fn strip_ansi_codes(s: &str) -> String {
    if !s.contains('\x1b') {
        return s.to_string();
    }
    let mut out = String::with_capacity(s.len());
    for e in elements(s) {
        if let Element::Text(t) = e {
            out.push_str(t);
        }
    }
    out
}

pub fn measure_text_width(s: &str) -> usize {
    if s.contains('\x1b') {
        strip_ansi_codes(s).width()
    } else {
        s.width()
    }
}

pub fn string_width(s: &str) -> usize {
    s.width()
}

/// Truncate string such that `tail` is present as a suffix, and the total display width is
/// at most `display_width`, preserving ANSI escape sequences.
pub fn truncate_str(s: &str, display_width: usize, tail: &str) -> String {
    let items = elements(s);
    let width = measure_text_width(s);
    if width <= display_width {
        return s.to_string();
    }
    let tail_width = measure_text_width(tail);
    let mut used = 0;
    let mut result = String::new();
    let mut result_tail = String::new();
    let max = display_width.saturating_sub(tail_width);
    let mut done = false;
    for e in items {
        match e {
            Element::Text(t) => {
                if done {
                    continue;
                }
                for g in t.graphemes(true) {
                    let w = g.width();
                    if used + w > max {
                        done = true;
                        break;
                    }
                    used += w;
                    result.push_str(g);
                }
            }
            Element::Csi(c) | Element::Osc(c) | Element::Esc(c) => {
                if done {
                    result_tail.push_str(c);
                } else {
                    result.push_str(c);
                }
            }
        }
    }
    result.push_str(tail);
    result.push_str(&result_tail);
    result
}

/// Return the first index (byte offset) after skipping n visible graphemes, preserving ANSI
/// sequences: returns the substring starting after `start` visible graphemes, with ANSI codes kept.
pub fn ansi_preserving_slice(s: &str, start: usize) -> String {
    let mut out = String::new();
    let mut skipped = 0;
    for e in elements(s) {
        match e {
            Element::Text(t) => {
                for g in t.graphemes(true) {
                    if skipped < start {
                        skipped += 1;
                    } else {
                        out.push_str(g);
                    }
                }
            }
            Element::Csi(c) | Element::Osc(c) | Element::Esc(c) => out.push_str(c),
        }
    }
    out
}

/// Parse SGR parameters, updating style.
pub fn apply_sgr(style: &mut Style, params: &str) {
    let parts: Vec<&str> = if params.is_empty() { vec!["0"] } else { params.split(';').collect() };
    let mut i = 0;
