    while i < nums.len() {
        let n = match nums[i] {
            Some(n) => n,
            None => {
                i += 1;
                continue;
            }
        };
        match n {
            0 => *style = Style::default(),
            1 => style.is_bold = true,
            2 => style.is_dimmed = true,
            3 => style.is_italic = true,
            4 => style.is_underline = true,
            5 => style.is_blink = true,
