            100..=107 => style.background = Some(Color::Fixed((n - 100 + 8) as u8)),
            _ => {}
        }
        i += 1;
    }
}

fn basic_color(n: u32) -> Color {
    match n {
        0 => Color::Black,
        1 => Color::Red,
        2 => Color::Green,
        3 => Color::Yellow,
        4 => Color::Blue,
        5 => Color::Purple,
        6 => Color::Cyan,
        _ => Color::White,
    }
}

fn parse_extended(rest: &[Option<u32>]) -> (Option<Color>, usize) {
    match rest.first() {
        Some(Some(5)) => match rest.get(1) {
            Some(Some(n)) => (Some(Color::Fixed(*n as u8)), 2),
            _ => (None, 1),
