                    if last.0 == style {
                        last.1.push_str(t);
                        continue;
                    }
                }
                sections.push((style, t.to_string()));
            }
            Element::Csi(c) => {
                if c.ends_with('m') {
                    apply_sgr(&mut style, &c[2..c.len() - 1]);
                }
            }
            _ => {}
        }
    }
    sections
