// Token alignment via edit-distance dynamic programming.

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum Operation {
    NoOp,
    Substitution,
    Deletion,
    Insertion,
}

#[derive(Copy, Clone, Debug)]
struct Cell {
    parent: usize,
    operation: Operation,
    cost: usize,
}

pub struct Alignment<'a> {
    pub x: Vec<&'a str>,
    pub y: Vec<&'a str>,
    table: Vec<Cell>,
    dim: [usize; 2],
}

const SUBSTITUTION_COST: usize = 2;
const DELETION_COST: usize = 1;
const INSERTION_COST: usize = 1;

impl<'a> Alignment<'a> {
    pub fn new(x: Vec<&'a str>, y: Vec<&'a str>) -> Self {
        let dim = [y.len() + 1, x.len() + 1];
        let table = vec![Cell { parent: 0, operation: Operation::NoOp, cost: 0 }; dim[0] * dim[1]];
        let mut a = Alignment { x, y, table, dim };
        a.fill();
        a
    }

    fn index(&self, i: usize, j: usize) -> usize {
        j * self.dim[1] + i
    }

    fn fill(&mut self) {
        for i in 1..self.dim[1] {
            self.table[i] = Cell { parent: i - 1, operation: Operation::Deletion, cost: i * DELETION_COST };
        }
        for j in 1..self.dim[0] {
            self.table[j * self.dim[1]] =
                Cell { parent: (j - 1) * self.dim[1], operation: Operation::Insertion, cost: j * INSERTION_COST };
        }
        for i in 0..self.x.len() {
            for j in 0..self.y.len() {
                let (left, diag, up) = (self.index(i, j + 1), self.index(i, j), self.index(i + 1, j));
                let equal = self.x[i] == self.y[j];
                let candidates = [
                    Cell { parent: up, operation: Operation::Insertion, cost: self.table[up].cost + INSERTION_COST },
                    Cell { parent: left, operation: Operation::Deletion, cost: self.table[left].cost + DELETION_COST },
                    Cell {
                        parent: diag,
                        operation: if equal { Operation::NoOp } else { Operation::Substitution },
                        cost: self.table[diag].cost + if equal { 0 } else { SUBSTITUTION_COST },
                    },
                ];
                let mut best = candidates[0];
                for c in &candidates[1..] {
                    if c.cost < best.cost {
                        best = *c;
                    }
                }
                let idx = self.index(i + 1, j + 1);
                self.table[idx] = best;
            }
        }
    }

    pub fn operations(&self) -> Vec<Operation> {
        let mut ops = std::collections::VecDeque::new();
        let mut cell = &self.table[self.index(self.x.len(), self.y.len())];
        if self.x.is_empty() && self.y.is_empty() {
            return Vec::new();
        }
        loop {
            ops.push_front(cell.operation);
            if cell.parent == 0 {
                break;
            }
            cell = &self.table[cell.parent];
        }
        Vec::from(ops)
    }

    pub fn coalesced_operations(&self) -> Vec<(Operation, usize)> {
        let mut out: Vec<(Operation, usize)> = Vec::new();
        for op in self.operations() {
            if let Some(last) = out.last_mut() {
                if last.0 == op {
                    last.1 += 1;
                    continue;
                }
            }
            out.push((op, 1));
        }
        out
    }
}
