// Inference of within-line edits.
use crate::align::{self, Alignment};
use regex::Regex;
use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

pub fn tokenize<'a>(line: &'a str, regex: &Regex) -> Vec<&'a str> {
    let mut tokens = Vec::new();
    let mut offset = 0;
    for m in regex.find_iter(line) {
        if m.start() == m.end() {
            continue;
        }
        if offset == 0 && m.start() > 0 {
            tokens.push("");
        }
        for t in line[offset..m.start()].graphemes(true) {
            tokens.push(t);
        }
        tokens.push(&line[m.start()..m.end()]);
        offset = m.end();
    }
    if offset < line.len() {
        if offset == 0 {
            tokens.push("");
        }
        for t in line[offset..].graphemes(true) {
            tokens.push(t);
        }
    }
    tokens
}

pub type Annotated<'a, T> = Vec<(T, &'a str)>;

#[allow(clippy::too_many_arguments)]
fn annotate<'a, T: Copy>(
    alignment: &Alignment<'a>,
    noop_deletion: T,
    deletion: T,
    noop_insertion: T,
    insertion: T,
    minus_line: &'a str,
    plus_line: &'a str,
) -> (Annotated<'a, T>, Annotated<'a, T>, f64) {
    let mut am = Vec::new();
    let mut ap = Vec::new();
    let (mut x_off, mut y_off) = (0usize, 0usize);
    let (mut mo, mut po) = (0usize, 0usize);
    let (mut numer, mut denom) = (0usize, 0usize);
    let section = |tokens: &[&str], off: usize, n: usize| -> usize { tokens[off..off + n].iter().map(|t| t.len()).sum() };
    for (op, n) in alignment.coalesced_operations() {
        match op {
            align::Operation::Deletion => {
                let len = section(&alignment.x, x_off, n);
                let s = &minus_line[mo..mo + len];
                let w = s.trim().width();
                numer += w;
                denom += w;
                am.push((deletion, s));
                mo += len;
                x_off += n;
            }
            align::Operation::Insertion => {
                let len = section(&alignment.y, y_off, n);
                let s = &plus_line[po..po + len];
                let w = s.trim().width();
                numer += w;
                denom += w;
                ap.push((insertion, s));
                po += len;
                y_off += n;
            }
            align::Operation::NoOp => {
                let mlen = section(&alignment.x, x_off, n);
                let plen = section(&alignment.y, y_off, n);
                let ms = &minus_line[mo..mo + mlen];
                let ps = &plus_line[po..po + plen];
                denom += ms.trim().width() + ps.trim().width();
                am.push((noop_deletion, ms));
                ap.push((noop_insertion, ps));
                mo += mlen;
                po += plen;
                x_off += n;
                y_off += n;
            }
            align::Operation::Substitution => {
                let mlen = section(&alignment.x, x_off, n);
                let plen = section(&alignment.y, y_off, n);
                let ms = &minus_line[mo..mo + mlen];
                let ps = &plus_line[po..po + plen];
                let (wm, wp) = (ms.trim().width(), ps.trim().width());
                numer += wm + wp;
                denom += wm + wp;
                am.push((deletion, ms));
                ap.push((insertion, ps));
                mo += mlen;
                po += plen;
                x_off += n;
                y_off += n;
            }
        }
    }
    let d = if denom > 0 { numer as f64 / denom as f64 } else { 0.0 };
    (am, ap, d)
}

pub type LineAlignment = Vec<(Option<usize>, Option<usize>)>;

#[allow(clippy::too_many_arguments, clippy::type_complexity)]
pub fn infer_edits<'a, T: Copy>(
    minus_lines: &[&'a str],
    plus_lines: &[&'a str],
    noop_deletions: &[T],
    deletion: T,
    noop_insertions: &[T],
    insertion: T,
    regex: &Regex,
    max_line_distance: f64,
    max_line_distance_for_naively_paired_lines: f64,
) -> (Vec<Annotated<'a, T>>, Vec<Annotated<'a, T>>, LineAlignment) {
    let mut am_lines = Vec::new();
    let mut ap_lines = Vec::new();
    let mut alignment_out = Vec::new();
    let mut plus_index = 0;
    let plus_tokens: Vec<Vec<&str>> = plus_lines.iter().map(|l| tokenize(l, regex)).collect();
    'minus: for (minus_index, minus_line) in minus_lines.iter().enumerate() {
        let minus_tokens = tokenize(minus_line, regex);
        let mut considered = 0;
        for (k, plus_line) in plus_lines[plus_index..].iter().enumerate() {
            let alignment = Alignment::new(minus_tokens.clone(), plus_tokens[plus_index + k].clone());
            let (am, ap, distance) = annotate(
                &alignment,
                noop_deletions[minus_index],
                deletion,
                noop_insertions[plus_index],
                insertion,
                minus_line,
                plus_line,
            );
            if (minus_lines.len() == plus_lines.len() && distance <= max_line_distance_for_naively_paired_lines)
                || distance <= max_line_distance
            {
                for pl in &plus_lines[plus_index..plus_index + considered] {
                    ap_lines.push(vec![(noop_insertions[plus_index], *pl)]);
                    alignment_out.push((None, Some(plus_index)));
                    plus_index += 1;
                }
                am_lines.push(am);
                ap_lines.push(ap);
                alignment_out.push((Some(minus_index), Some(plus_index)));
                plus_index += 1;
                continue 'minus;
            } else {
                considered += 1;
            }
        }
        am_lines.push(vec![(noop_deletions[minus_index], *minus_line)]);
        alignment_out.push((Some(minus_index), None));
    }
    for pl in &plus_lines[plus_index..] {
        ap_lines.push(vec![(noop_insertions[plus_index], *pl)]);
        alignment_out.push((None, Some(plus_index)));
        plus_index += 1;
    }
    (am_lines, ap_lines, alignment_out)
}

pub fn make_lines_have_homolog(line_alignment: &LineAlignment) -> (Vec<bool>, Vec<bool>) {
    let mut minus = Vec::new();
    let mut plus = Vec::new();
    for (m, p) in line_alignment {
        match (m, p) {
            (Some(_), Some(_)) => {
                minus.push(true);
                plus.push(true);
            }
            (Some(_), None) => minus.push(false),
            (None, Some(_)) => plus.push(false),
            _ => {}
        }
    }
    (minus, plus)
}
