// Format string parsing for line numbers / blame.
use regex::Regex;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Align {
    Left,
    Center,
    Right,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Placeholder {
    pub prefix: String,
    pub placeholder: Option<String>,
    pub alignment_spec: Option<Align>,
    pub width: Option<usize>,
    pub precision: Option<usize>,
    pub fmt_type: String,
    pub suffix: String,
}

pub fn make_placeholder_regex(labels: &[&str]) -> Regex {
    Regex::new(&format!(
        r"\{{({})(?::(?:([^<^>])?([<^>]))?(\d+)?(?:\.(\d+))?(?:_?([A-Za-z][0-9A-Za-z_-]*))?)?\}}",
        labels.join("|")
    ))
    .unwrap()
}

pub const ODD_PAD_CHAR: char = ' ';

pub fn parse_line_number_format(format_string: &str, re: &Regex, mut prefix_with_space: bool) -> Vec<Placeholder> {
    let mut out = Vec::new();
    let mut offset = 0;
    let mut expand = |p: String| -> String {
        if prefix_with_space {
            prefix_with_space = false;
            format!("{}{}", ODD_PAD_CHAR, p)
        } else {
            p
        }
    };
    for caps in re.captures_iter(format_string) {
        let m = caps.get(0).unwrap();
        let prefix = expand(format_string[offset..m.start()].to_string());
        out.push(Placeholder {
            prefix,
            placeholder: caps.get(1).map(|m| m.as_str().to_string()),
            alignment_spec: caps.get(3).map(|m| match m.as_str() {
                "<" => Align::Left,
                ">" => Align::Right,
                _ => Align::Center,
            }),
            width: caps.get(4).and_then(|m| m.as_str().parse().ok()),
            precision: caps.get(5).and_then(|m| m.as_str().parse().ok()),
            fmt_type: caps.get(6).map(|m| m.as_str().to_string()).unwrap_or_default(),
            suffix: format_string[m.end()..].to_string(),
        });
        offset = m.end();
    }
    if offset == 0 {
        out.push(Placeholder {
            prefix: String::new(),
            placeholder: None,
            alignment_spec: None,
            width: None,
            precision: None,
            fmt_type: String::new(),
            suffix: expand(format_string.to_string()),
        });
    }
    out
}

fn truncate_chars(s: &str, n: usize) -> String {
    s.chars().take(n).collect()
}

fn std_pad(s: &str, width: usize, align: Align) -> String {
    let len = s.chars().count();
    if len >= width {
        return s.to_string();
    }
    let total = width - len;
    let (l, r) = match align {
        Align::Left => (0, total),
        Align::Right => (total, 0),
        Align::Center => (total / 2, total - total / 2),
    };
    format!("{}{}{}", " ".repeat(l), s, " ".repeat(r))
}

/// Pad a number, using "center-right" alignment for centered numbers.
pub fn pad_number(n: usize, width: usize, align: Align, precision: Option<usize>) -> String {
    let s = n.to_string();
    let space = if align == Align::Center && width % 2 == 0 && s.len() % 2 == 1 { " " } else { "" };
    let _ = precision;
    let mut result = format!("{}{}", space, std_pad(&s, width, align));
    if space == " " {
        result.pop();
    }
    result
}

/// Pad a string (strings are left-centered).
pub fn pad_str(s: &str, width: usize, align: Align, precision: Option<usize>) -> String {
    let s = match precision {
        Some(p) => truncate_chars(s, p),
        None => s.to_string(),
    };
    std_pad(&s, width, align)
}
