// Line number columns.
use crate::ansi_term;
use crate::config::Config;
use crate::delta::State;
use crate::format::{self, Align, Placeholder};
use crate::style::Style;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum PanelSide {
    Left,
    Right,
}

#[derive(Clone, Debug)]
pub struct LineNumbersData {
    pub format_data: [Vec<Placeholder>; 2],
    pub line_number: [usize; 2],
    pub hunk_max_line_number_width: usize,
    pub plus_file: String,
}

impl LineNumbersData {
    pub fn from_format_strings(left: &str, right: &str, use_full_width: bool) -> LineNumbersData {
        let re = format::make_placeholder_regex(&["nm", "np"]);
        LineNumbersData {
            format_data: [
                format::parse_line_number_format(left, &re, false),
                format::parse_line_number_format(right, &re, use_full_width),
            ],
            line_number: [0, 0],
            hunk_max_line_number_width: 0,
            plus_file: String::new(),
        }
    }

    pub fn empty_for_sbs(use_full_width: bool) -> LineNumbersData {
        let mut d = LineNumbersData::from_format_strings("", "", use_full_width);
        if use_full_width {
            d.format_data = [
                vec![Placeholder {
                    prefix: String::new(),
                    placeholder: None,
                    alignment_spec: None,
                    width: None,
                    precision: None,
                    fmt_type: String::new(),
                    suffix: String::new(),
                }],
                vec![Placeholder {
                    prefix: format::ODD_PAD_CHAR.to_string(),
                    placeholder: None,
                    alignment_spec: None,
                    width: None,
                    precision: None,
                    fmt_type: String::new(),
                    suffix: String::new(),
                }],
            ];
        } else {
            d.format_data = [Vec::new(), Vec::new()];
        }
        d
    }

    pub fn initialize_hunk(&mut self, line_numbers: &[(usize, usize)], plus_file: String) {
        if line_numbers.is_empty() {
            return;
        }
        self.line_number = [line_numbers[0].0, line_numbers[line_numbers.len() - 1].0];
        let max = line_numbers.iter().map(|(n, d)| n + d).max().unwrap();
        self.hunk_max_line_number_width = 1 + (max as f64).log10().floor() as usize;
        if max == 0 {
            self.hunk_max_line_number_width = 1;
        }
        self.plus_file = plus_file;
    }

    fn placeholder_width(&self, p: &Placeholder) -> usize {
        match &p.placeholder {
            Some(_) => p.width.unwrap_or(0).max(self.hunk_max_line_number_width),
            None => 0,
        }
    }

    pub fn formatted_width(&self) -> [usize; 2] {
        let w = |fd: &Vec<Placeholder>| -> usize {
            let mut sum = 0;
            for (i, p) in fd.iter().enumerate() {
                sum += crate::ansi::string_width(&p.prefix) + self.placeholder_width(p);
                if i == fd.len() - 1 {
                    sum += crate::ansi::string_width(&p.suffix);
                }
            }
            sum
        };
        [w(&self.format_data[0]), w(&self.format_data[1])]
    }
}

pub fn format_and_paint_line_numbers(
    data: &mut LineNumbersData,
    state: &State,
    panel: Option<PanelSide>,
    config: &Config,
) -> Vec<(ansi_term::Style, String)> {
    let nr_left = data.line_number[0];
    let nr_right = data.line_number[1];
    let minus_style = config.line_numbers_minus_style;
    let zero_style = config.line_numbers_zero_style;
    let plus_style = config.line_numbers_plus_style;
    let ((minus_number, plus_number), (ms, ps)) = match state {
        State::HunkMinus(..) => {
            data.line_number[0] += 1;
            ((Some(nr_left), None), (minus_style, plus_style))
        }
        State::HunkMinusWrapped => ((None, None), (minus_style, plus_style)),
        State::HunkZero(..) => {
            data.line_number[0] += 1;
            data.line_number[1] += 1;
            ((Some(nr_left), Some(nr_right)), (zero_style, zero_style))
        }
        State::HunkZeroWrapped => ((None, None), (zero_style, zero_style)),
        State::HunkPlus(..) => {
            data.line_number[1] += 1;
            ((None, Some(nr_right)), (minus_style, plus_style))
        }
        State::HunkPlusWrapped => ((None, None), (minus_style, plus_style)),
        _ => return Vec::new(),
    };
    let (emit_left, emit_right) = match (config.side_by_side, panel) {
        (false, _) => (true, true),
        (true, Some(PanelSide::Left)) => (true, false),
        (true, Some(PanelSide::Right)) => (false, true),
        (true, None) => (true, true),
    };
    let mut out = Vec::new();
    if emit_left {
        out.extend(field(data, 0, &ms, &ps, minus_number, plus_number, config));
    }
    if emit_right {
        out.extend(field(data, 1, &ms, &ps, minus_number, plus_number, config));
    }
    out
}

fn field(
    data: &LineNumbersData,
    side: usize,
    minus_style: &Style,
    plus_style: &Style,
    minus_number: Option<usize>,
    plus_number: Option<usize>,
    config: &Config,
) -> Vec<(ansi_term::Style, String)> {
    let min_field_width = data.hunk_max_line_number_width;
    let style = if side == 0 { config.line_numbers_left_style } else { config.line_numbers_right_style };
    let mut out = Vec::new();
    let mut suffix = String::new();
    for p in &data.format_data[side] {
        out.push((style.ansi_term_style, p.prefix.clone()));
        let align = p.alignment_spec.unwrap_or(Align::Center);
        let width = p.width.unwrap_or(0).max(min_field_width);
        match p.placeholder.as_deref() {
            Some("nm") => out.push((
                minus_style.ansi_term_style,
                format_line_number(minus_number, align, width, p.precision, None, config),
            )),
            Some("np") => out.push((
                plus_style.ansi_term_style,
                format_line_number(plus_number, align, width, p.precision, Some(&data.plus_file), config),
            )),
            _ => {}
        }
        suffix = p.suffix.clone();
    }
    out.push((style.ansi_term_style, suffix));
    out
}

fn format_line_number(
    n: Option<usize>,
    align: Align,
    width: usize,
    precision: Option<usize>,
    plus_file: Option<&str>,
    config: &Config,
) -> String {
    match n {
        None => " ".repeat(width),
        Some(n) => {
            let padded = format::pad_number(n, width, align, precision);
            if config.hyperlinks {
                if let Some(file) = plus_file {
                    if let Some(abs) = crate::hyperlinks::absolute_path(file, config) {
                        return crate::hyperlinks::format_osc8_file_path_hyperlink(&abs, Some(n), &padded, config);
                    }
                    return file.to_string();
                }
            }
            padded
        }
    }
}
