// Painting of diff lines.
use crate::ansi;
use crate::ansi_term::{self, Color};
use crate::color::to_ansi_color;
use crate::config::Config;
use crate::delta::{DiffType, MergeParents, State};
use crate::edits;
use crate::line_numbers::{self, LineNumbersData, PanelSide};
use crate::style::Style;
use crate::syntax::highlighter::{Highlighter, SynStyle, NULL_SYN_STYLE};
use crate::syntax::languages::Lang;
use unicode_segmentation::UnicodeSegmentation;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum BgFillMethod {
    TryAnsiSequence,
    Spaces,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum BgShouldFill {
    With(BgFillMethod),
    No,
}

impl Default for BgShouldFill {
    fn default() -> Self {
        BgShouldFill::With(BgFillMethod::TryAnsiSequence)
    }
}

pub type LineSections<'a, S> = Vec<(S, &'a str)>;

pub enum StyleSectionSpecifier<'a> {
    Style(Style),
    StyleSections(LineSections<'a, Style>),
}

pub struct Painter<'c> {
    pub minus_lines: Vec<(String, State)>,
    pub plus_lines: Vec<(String, State)>,
    pub out: String,
    pub lang: Lang,
    pub highlighter: Option<Highlighter>,
    pub config: &'c Config,
    pub output_buffer: String,
    pub line_numbers_data: Option<LineNumbersData>,
    pub merge_conflict_lines: crate::handlers::merge_conflict::MergeConflictLines,
    pub merge_conflict_commit_names: crate::handlers::merge_conflict::MergeConflictCommitNames,
}

pub fn expand_tabs<'a, I: Iterator<Item = &'a str>>(line: I, tab_width: usize) -> String {
    if tab_width > 0 {
        let rep = " ".repeat(tab_width);
        let mut s = String::new();
        for g in line {
            if g == "\t" {
                s.push_str(&rep);
            } else {
                s.push_str(g);
            }
        }
        s
    } else {
        line.collect()
    }
}

impl<'c> Painter<'c> {
    pub fn new(config: &'c Config) -> Painter<'c> {
        let lang = crate::syntax::languages::get_syntax(None, &config.default_language);
        let line_numbers_data = if config.line_numbers {
            Some(LineNumbersData::from_format_strings(
                &config.line_numbers_left_format,
                &config.line_numbers_right_format,
                config.side_by_side && config.use_full_panel_width_odd_fix,
            ))
        } else if config.side_by_side {
            Some(LineNumbersData::empty_for_sbs(config.use_full_panel_width_odd_fix))
        } else {
            None
        };
        Painter {
            minus_lines: Vec::new(),
            plus_lines: Vec::new(),
            out: String::new(),
            lang,
            highlighter: None,
            config,
            output_buffer: String::new(),
            line_numbers_data,
            merge_conflict_lines: Default::default(),
            merge_conflict_commit_names: Default::default(),
        }
    }

    pub fn set_syntax(&mut self, filename: Option<&str>) {
        self.lang = crate::syntax::languages::get_syntax(filename, &self.config.default_language);
    }

    pub fn set_highlighter(&mut self) {
        if let Some(theme) = self.config.syntax_theme {
            self.highlighter = Some(Highlighter::new(self.lang, theme));
        }
    }

    pub fn emit(&mut self) {
        self.out.push_str(&self.output_buffer);
        self.output_buffer.clear();
    }

    pub fn expand_tabs_str(&self, s: &str) -> String {
        expand_tabs(s.graphemes(true), self.config.tab_width)
    }

    pub fn paint_buffered_minus_and_plus_lines(&mut self) {
        if self.minus_lines.is_empty() && self.plus_lines.is_empty() {
            return;
        }
        let minus = std::mem::take(&mut self.minus_lines);
        let plus = std::mem::take(&mut self.plus_lines);
        paint_minus_and_plus_lines(
            &minus,
            &plus,
            &mut self.line_numbers_data,
            &mut self.highlighter,
            &mut self.output_buffer,
            self.config,
        );
    }

    pub fn paint_zero_line(&mut self, line: &str, state: State) {
        let lines = vec![(line.to_string(), state.clone())];
        let syntax_sections = get_syntax_style_sections_for_lines(&lines, &mut self.highlighter, self.config);
        let mut diff_sections = vec![vec![(self.config.zero_style, lines[0].0.as_str())]];
        update_diff_style_sections_for_raw(&lines, &mut diff_sections, self.config);
        if self.config.side_by_side {
            crate::side_by_side::paint_zero_lines_side_by_side(
                &lines[0].0,
                &state,
                &syntax_sections[0],
                &diff_sections[0],
                &mut self.output_buffer,
                self.config,
                &mut self.line_numbers_data,
                painted_prefix(&state, self.config),
                BgShouldFill::With(BgFillMethod::Spaces),
            );
        } else {
            paint_lines(
                &lines,
                &syntax_sections,
                &diff_sections,
                &[false],
                &mut self.output_buffer,
                self.config,
                &mut self.line_numbers_data,
                None,
                BgShouldFill::default(),
            );
        }
    }

    pub fn syntax_highlight_and_paint_line(
        &mut self,
        line: &str,
        style_sections: StyleSectionSpecifier,
        state: State,
        bg_fill: BgShouldFill,
    ) {
        let lines = vec![(self.expand_tabs_str(line), state)];
        let syntax_sections = get_syntax_style_sections_for_lines(&lines, &mut self.highlighter, self.config);
        let diff_sections = match style_sections {
            StyleSectionSpecifier::Style(style) => vec![vec![(style, lines[0].0.as_str())]],
            StyleSectionSpecifier::StyleSections(s) => vec![s],
        };
        let mut none = None;
        paint_lines(&lines, &syntax_sections, &diff_sections, &[false], &mut self.output_buffer, self.config, &mut none, None, bg_fill);
    }
}

pub fn should_compute_syntax_highlighting(state: &State, config: &Config) -> bool {
    if config.syntax_theme.is_none() {
        return false;
    }
    match state {
        State::HunkMinus(_, None) => {
            config.minus_style.is_syntax_highlighted
                || config.minus_emph_style.is_syntax_highlighted
                || config.minus_non_emph_style.is_syntax_highlighted
        }
        State::HunkZero(_, None) => config.zero_style.is_syntax_highlighted,
        State::HunkPlus(_, None) => {
            config.plus_style.is_syntax_highlighted
                || config.plus_emph_style.is_syntax_highlighted
                || config.plus_non_emph_style.is_syntax_highlighted
        }
        _ => true,
    }
}

pub fn get_syntax_style_sections_for_lines<'a>(
    lines: &'a [(String, State)],
    highlighter: &mut Option<Highlighter>,
    config: &Config,
) -> Vec<LineSections<'a, SynStyle>> {
    let mut out = Vec::new();
    for (line, state) in lines {
        match highlighter {
            Some(h) if should_compute_syntax_highlighting(state, config) => {
                let max = config.max_syntax_length;
                if max > 0 && line.len() > max {
                    let mut cut = max;
                    while !line.is_char_boundary(cut) {
                        cut -= 1;
                    }
                    let (a, b) = line.split_at(cut);
                    let mut s = h.highlight_line(a);
                    s.push((NULL_SYN_STYLE, b));
                    out.push(s);
                } else {
                    out.push(h.highlight_line(line));
                }
            }
            _ => out.push(vec![(NULL_SYN_STYLE, line.as_str())]),
        }
    }
    out
}

pub fn painted_prefix(state: &State, config: &Config) -> Option<(ansi_term::Style, String)> {
    match state {
        State::HunkMinus(DiffType::Combined(MergeParents::Prefix(p), _), _) => {
            Some((config.minus_style.ansi_term_style, p.clone()))
        }
        State::HunkZero(DiffType::Combined(MergeParents::Prefix(p), _), _) => {
            Some((config.zero_style.ansi_term_style, p.clone()))
        }
        State::HunkPlus(DiffType::Combined(MergeParents::Prefix(p), _), _) => {
            Some((config.plus_style.ansi_term_style, p.clone()))
        }
        State::HunkMinus(DiffType::Unified, _) if config.keep_plus_minus_markers => {
            Some((config.minus_style.ansi_term_style, "-".to_string()))
        }
        State::HunkPlus(DiffType::Unified, _) if config.keep_plus_minus_markers => {
            Some((config.plus_style.ansi_term_style, "+".to_string()))
        }
        _ => None,
    }
}

fn paint_minus_and_plus_lines(
    minus: &[(String, State)],
    plus: &[(String, State)],
    line_numbers_data: &mut Option<LineNumbersData>,
    highlighter: &mut Option<Highlighter>,
    output_buffer: &mut String,
    config: &Config,
) {
    let syn_minus = get_syntax_style_sections_for_lines(minus, highlighter, config);
    let syn_plus = get_syntax_style_sections_for_lines(plus, highlighter, config);
    let (diff_minus, diff_plus, line_alignment) = get_diff_style_sections(minus, plus, config);
    let (homolog_minus, homolog_plus) = edits::make_lines_have_homolog(&line_alignment);
    if config.side_by_side {
        crate::side_by_side::paint_minus_and_plus_lines_side_by_side(
            minus,
            plus,
            &syn_minus,
            &syn_plus,
            &diff_minus,
            &diff_plus,
            &homolog_minus,
            &homolog_plus,
            &line_alignment,
            line_numbers_data,
            output_buffer,
            config,
        );
    } else {
        if !minus.is_empty() {
            paint_lines(
                minus,
                &syn_minus,
                &diff_minus,
                &homolog_minus,
                output_buffer,
                config,
                line_numbers_data,
                Some(config.minus_empty_line_marker_style),
                BgShouldFill::default(),
            );
        }
        if !plus.is_empty() {
            paint_lines(
                plus,
                &syn_plus,
                &diff_plus,
                &homolog_plus,
                output_buffer,
                config,
                line_numbers_data,
                Some(config.plus_empty_line_marker_style),
                BgShouldFill::default(),
            );
        }
    }
}

#[allow(clippy::too_many_arguments)]
pub fn paint_lines(
    lines: &[(String, State)],
    syntax_sections: &[LineSections<SynStyle>],
    diff_sections: &[LineSections<Style>],
    lines_have_homolog: &[bool],
    output_buffer: &mut String,
    config: &Config,
    line_numbers_data: &mut Option<LineNumbersData>,
    empty_line_style: Option<Style>,
    bg_fill: BgShouldFill,
) {
    for (i, (_, state)) in lines.iter().enumerate() {
        let (mut line, line_is_empty) = paint_line(
            &syntax_sections[i],
            &diff_sections[i],
            state,
            line_numbers_data,
            None,
            painted_prefix(state, config),
            config,
        );
        let (fill_mode, fill_style) = get_should_right_fill_background_color_and_fill_style(
            &diff_sections[i],
            Some(lines_have_homolog[i]),
            state,
            bg_fill,
            config,
        );
        match fill_mode {
            Some(BgFillMethod::TryAnsiSequence) => {
                right_fill_background_color(&mut line, fill_style);
            }
            Some(BgFillMethod::Spaces) => {
                let w = ansi::measure_text_width(&line);
                let n = config.available_terminal_width.saturating_sub(w);
                line.push_str(&fill_style.paint(&" ".repeat(n)));
            }
            None => {
                if line_is_empty {
                    if let Some(s) = empty_line_style {
                        mark_empty_line(&s, &mut line, None);
                    }
                }
            }
        }
        output_buffer.push_str(&line);
        output_buffer.push('\n');
    }
}

pub fn right_fill_background_color(line: &mut String, fill_style: Style) {
    line.push_str(&fill_style.paint(ansi::ANSI_CSI_CLEAR_TO_EOL));
}

pub fn mark_empty_line(style: &Style, line: &mut String, marker: Option<&str>) {
    line.push_str(&style.paint(marker.unwrap_or(ansi::ANSI_CSI_CLEAR_TO_BOL)));
}

pub fn get_should_right_fill_background_color_and_fill_style(
    diff_sections: &[(Style, &str)],
    line_has_homolog: Option<bool>,
    state: &State,
    bg_fill: BgShouldFill,
    config: &Config,
) -> (Option<BgFillMethod>, Style) {
    let fill_style = match state {
        State::HunkMinus(_, None) | State::HunkMinusWrapped => {
            if line_has_homolog == Some(true) {
                config.minus_non_emph_style
            } else {
                config.minus_style
            }
        }
        State::HunkZero(_, None) | State::HunkZeroWrapped => config.zero_style,
        State::HunkPlus(_, None) | State::HunkPlusWrapped => {
            if line_has_homolog == Some(true) {
                config.plus_non_emph_style
            } else {
                config.plus_style
            }
        }
        State::HunkMinus(_, Some(_)) | State::HunkPlus(_, Some(_)) | State::HunkZero(_, Some(_)) => {
            // last "real" style
            let mut st = Style::default();
            for (s, t) in diff_sections.iter().rev() {
                if !t.is_empty() && *t != "\n" {
                    st = *s;
                    break;
                }
            }
            st
        }
        State::Blame(_) => diff_sections.first().map(|(s, _)| *s).unwrap_or_default(),
        _ => Style::default(),
    };
    match (fill_style.get_background_color().is_some(), bg_fill) {
        (false, _) | (_, BgShouldFill::No) => (None, fill_style),
        (_, BgShouldFill::With(mode)) => {
            if config.background_color_extends_to_terminal_width {
                (Some(mode), fill_style)
            } else {
                (None, fill_style)
            }
        }
    }
}

/// Return painted line (maybe prefixed with line numbers field) and an is_empty? boolean.
pub fn paint_line(
    syntax_sections: &[(SynStyle, &str)],
    diff_sections: &[(Style, &str)],
    state: &State,
    line_numbers_data: &mut Option<LineNumbersData>,
    panel: Option<PanelSide>,
    mut painted_prefix: Option<(ansi_term::Style, String)>,
    config: &Config,
) -> (String, bool) {
    let mut parts: Vec<(ansi_term::Style, String)> = Vec::new();
    if config.line_numbers {
        if let Some(d) = line_numbers_data.as_mut() {
            parts.extend(line_numbers::format_and_paint_line_numbers(d, state, panel, config));
        }
    }
    let superimposed = superimpose_style_sections(syntax_sections, diff_sections, config.true_color);
    let mut handled_prefix = false;
    for (style, text) in superimposed {
        if !handled_prefix {
            if let Some(p) = painted_prefix.take() {
                parts.push(p);
            }
        }
        if !text.is_empty() {
            parts.push((style.ansi_term_style, text));
        }
        handled_prefix = true;
    }
    let is_empty = syntax_sections.is_empty();
    (ansi_term::ansi_strings(&parts), is_empty)
}

pub fn superimpose_style_sections(
    syntax_sections: &[(SynStyle, &str)],
    diff_sections: &[(Style, &str)],
    true_color: bool,
) -> Vec<(Style, String)> {
    let a: Vec<(SynStyle, char)> = syntax_sections.iter().flat_map(|(s, t)| t.chars().map(move |c| (*s, c))).collect();
    let b: Vec<(Style, char)> = diff_sections.iter().flat_map(|(s, t)| t.chars().map(move |c| (*s, c))).collect();
    let n = a.len().min(b.len());
    let mut out: Vec<(Style, String)> = Vec::new();
    if n == 0 {
        return out;
    }
    let make = |syn: SynStyle, style: Style| -> Style {
        if style.is_syntax_highlighted && !syn.is_null {
            let mut s = style;
            s.ansi_term_style.foreground = to_ansi_color(syn.foreground, true_color);
            s
        } else {
            style
        }
    };
    let mut cur_pair = (a[0].0, b[0].0);
    let mut cur = String::new();
    for i in 0..n {
        let pair = (a[i].0, b[i].0);
        if pair != cur_pair {
            out.push((make(cur_pair.0, cur_pair.1), std::mem::take(&mut cur)));
            cur_pair = pair;
        }
        cur.push(a[i].1);
    }
    if cur.ends_with('\n') {
        cur.pop();
    }
    out.push((make(cur_pair.0, cur_pair.1), cur));
    out
}

#[allow(clippy::type_complexity)]
pub fn get_diff_style_sections<'a>(
    minus: &'a [(String, State)],
    plus: &'a [(String, State)],
    config: &Config,
) -> (Vec<LineSections<'a, Style>>, Vec<LineSections<'a, Style>>, edits::LineAlignment) {
    let minus_lines: Vec<&str> = minus.iter().map(|(s, _)| s.as_str()).collect();
    let minus_styles: Vec<Style> = minus.iter().map(|(_, st)| *config.get_style(st)).collect();
    let plus_lines: Vec<&str> = plus.iter().map(|(s, _)| s.as_str()).collect();
    let plus_styles: Vec<Style> = plus.iter().map(|(_, st)| *config.get_style(st)).collect();
    let (mut dm, mut dp, alignment) = edits::infer_edits(
        &minus_lines,
        &plus_lines,
        &minus_styles,
        config.minus_emph_style,
        &plus_styles,
        config.plus_emph_style,
        &config.tokenization_regex,
        config.max_line_distance,
        config.max_line_distance_for_naively_paired_lines,
    );
    let minus_non_emph = if config.minus_non_emph_style != config.minus_emph_style {
        Some(config.minus_non_emph_style)
    } else {
        None
    };
    update_styles(&mut dm, config.whitespace_error_style, minus_non_emph);
    let plus_non_emph = if config.plus_non_emph_style != config.plus_emph_style {
        Some(config.plus_non_emph_style)
    } else {
        None
    };
    update_styles(&mut dp, config.whitespace_error_style, plus_non_emph);
    update_diff_style_sections_for_raw(minus, &mut dm, config);
    update_diff_style_sections_for_raw(plus, &mut dp, config);
    (dm, dp, alignment)
}

fn update_styles(sections: &mut [LineSections<Style>], whitespace_error_style: Style, non_emph_style: Option<Style>) {
    for line in sections.iter_mut() {
        let has_multiple = style_sections_contain_more_than_one_style(line);
        let should_update_non_emph = non_emph_style.is_some() && has_multiple;
        let is_ws_error = whitespace_error_style != Style::default() && is_whitespace_error(line);
        for (style, _s) in line.iter_mut() {
            if is_ws_error && (style.is_emph || !has_multiple) {
                *style = whitespace_error_style;
            } else if should_update_non_emph && !style.is_emph {
                *style = non_emph_style.unwrap();
            }
        }
    }
}

fn style_sections_contain_more_than_one_style(sections: &[(Style, &str)]) -> bool {
    if sections.len() > 1 {
        let first = sections[0].0;
        sections.iter().any(|(s, _)| *s != first)
    } else {
        false
    }
}

fn is_whitespace_error(sections: &[(Style, &str)]) -> bool {
    let mut any = false;
    for c in sections.iter().flat_map(|(_, s)| s.chars()) {
        if c == '\n' {
            return any;
        } else if c != ' ' && c != '\t' {
            return false;
        } else {
            any = true;
        }
    }
    false
}

/// For lines with raw ANSI (e.g. color-moved), replace style sections with those parsed from the raw line.
pub fn update_diff_style_sections_for_raw<'a>(
    lines: &'a [(String, State)],
    sections: &mut [LineSections<'a, Style>],
    config: &Config,
) {
    for (i, (line, state)) in lines.iter().enumerate() {
        let raw = match state {
            State::HunkMinus(_, Some(r)) | State::HunkZero(_, Some(r)) | State::HunkPlus(_, Some(r)) => r,
            _ => continue,
        };
        let non_raw = match state {
            State::HunkMinus(..) => config.minus_style,
            State::HunkZero(..) => config.zero_style,
            _ => config.plus_style,
        };
        sections[i] = parse_raw_style_sections(raw, line, non_raw, config);
    }
}

/// Parse a raw line into style sections aligned with the stripped line `line`.
fn parse_raw_style_sections<'a>(raw: &str, line: &'a str, _default: Style, config: &Config) -> LineSections<'a, Style> {
    let parsed = ansi::parse_style_sections(raw);
    let mut out = Vec::new();
    let mut offset = 0;
    for (astyle, text) in parsed {
        let len = text.len();
        if offset + len > line.len() {
            break;
        }
        let style = config.map_raw_style(astyle);
        out.push((style, &line[offset..offset + len]));
        offset += len;
    }
    if offset < line.len() {
        out.push((Style::default(), &line[offset..]));
    }
    out
}

